import{z as i,x as o,o as B,c as l,q as a,j as s,D as e,d as r,s as t,S as n}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"压力测试体系","description":"","frontmatter":{"title":"压力测试体系","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rk-stress-system.md","filePath":"quant/rk-stress-system.md","lastUpdated":1791413859000}'),d={name:"quant/rk-stress-system.md"};function C(p,E,F,m,D,_){const A=o("Mermaid");return B(),l("div",null,[E[2]||(E[2]=a('<h1 id="压力测试体系" tabindex="-1">压力测试体系 <a class="header-anchor" href="#压力测试体系" aria-label="Permalink to &quot;压力测试体系&quot;">​</a></h1><div class="epigraph"><p>压力测试不预测哪场危机，它回答另一个问题：如果波动、相关性与流动性同时坏掉，账上还剩多少——答案不进决策，问题就白问了。</p><footer>—— 据 BCBS, *Principles for Sound Stress Testing Practices and Supervision*, 2009/2018；CEBS, *Guidelines on Stress Testing*, 2010 整理</footer></div><p><a href="/quant/rk-model-governance-deep">上一课</a>把计量器本身纳入治理：模型入库、分级、验证、监测。留下一层缺口：分位数长在历史窗口的分布上，窗口外的联合极端——多因子同坏、相关性翻转、流动性蒸发——样本里没有。本课把正向压力测试搭成体系：情景库、严重度校准、结果对接；从失败反推的另一半见<a href="/quant/reverse-stress-test">反向压力测试</a>专课。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>压力测试的失败模式在 2008 年后监管复盘得很清楚：不是缺数字，是数字没人接。常见病有三类。情景不成库：临时拍脑袋，重复且漏机制，人走了情景就断档。校准无锚：冲击幅度随手设，\\(\\pm 20\\%\\) 与 \\(\\pm 40\\%\\) 的差别说不出机制依据，压力变成「更大的 VaR」——但历史窗口里根本没有这种联合状态，把分位数调高得不到它。结果不落决策：报告发出去了，不接限额、不接资本规划、不接应急资金计划，压力测试成为年报插画。三病同源：把压力当成日常计量的加压版，同一条流水线产出，自然同一种盲区。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>情景分三层入库。历史情景：1987 股灾、1998 LTCM、2008 次贷、2013 减债恐慌、2020 疫情，冻结因子路径原样重放，好处是联合变动真实、机制有案可查。假设情景：机制驱动构造——油价与汇率与利差同向的「滞胀组」、拍卖失败的「流动性组」，每个情景写明传导链：谁先动、谁传染、流动性假设是什么。敏感性层：单因子梯度与相关性加压矩阵，回答「哪个方向最脆」。校准给锚：幅度不小于对应历史段的实际联合变动，再加恶化假设——保证金螺旋让跌势自我放大时，幅度按螺旋参数上调。治理给对接：每个情景有 owner 与更新触发；结果必须落三处——限额（压力限额）、资本规划（ICAAP 或 CCAR 式自评）、应急资金计划（触发条件与动作表）。流动性压力单独跑：存款流失率、抵押品追缴、市场关闭假设组成资金情景，与市场情景联动重估。</p><p><span class="marginnote">「应急资金计划」可以翻译成提前写好的断粮预案：什么信号算开始缺钱（触发条件）、缺了先动哪笔钱、找谁借、按最坏假设能撑几天——全部平时写好、留好签字人，真到紧张时不用临场现想，也轮不到犹豫。</span></p>',8)),(B(),s(n,null,{default:e(()=>[t(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E9%80%89%E5%8E%86%E5%8F%B2%E6%AE%B5%EF%BC%9A%E5%A6%82%202008%20%E5%B9%B4%E6%9F%90%E4%B8%80%E5%91%A8%22%5D%20--%3E%20B%5B%22%E9%87%8F%E5%87%BA%E5%AE%9E%E9%99%85%E8%81%94%E5%90%88%E5%8F%98%E5%8A%A8%EF%BC%9A%E5%B9%85%E5%BA%A6%E9%94%9A%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%8F%A0%E5%8A%A0%E6%81%B6%E5%8C%96%E5%81%87%E8%AE%BE%EF%BC%9A%E4%BF%9D%E8%AF%81%E9%87%91%E8%9E%BA%E6%97%8B%E5%8F%82%E6%95%B0%22%5D%0A%20%20C%20--%3E%20D%5B%22%E6%83%85%E6%99%AF%E5%B9%85%E5%BA%A6%EF%BC%9A%E4%B8%8D%E5%B0%8F%E4%BA%8E%E9%94%9A%EF%BC%8C%E6%8C%89%E8%9E%BA%E6%97%8B%E4%B8%8A%E8%B0%83%22%5D%0A%20%20D%20--%3E%20E%5B%22%E8%81%94%E5%8A%A8%E9%87%8D%E4%BC%B0%EF%BC%9A%E5%B8%82%E5%9C%BA%E6%8D%9F%E5%A4%B1%E5%8A%A0%E4%BF%9D%E8%AF%81%E9%87%91%E8%BF%BD%E7%BC%B4%22%5D%0A%20%20E%20--%3E%20F%7B%22%E6%98%AF%E5%90%A6%E8%A7%A6%E5%8F%91%E8%A2%AB%E8%BF%AB%E5%8F%98%E7%8E%B0%EF%BC%9F%22%7D%0A%20%20F%20--%3E%7C%22%E6%98%AF%22%7C%20G%5B%22%E5%8F%98%E7%8E%B0%E6%8A%98%E4%BB%B7%E5%8A%A0%E6%B7%B1%E8%B7%8C%E5%B9%85%EF%BC%8C%E8%BF%AD%E4%BB%A3%E4%B8%8B%E4%B8%80%E8%BD%AE%22%5D%0A%20%20G%20--%3E%20E%0A%20%20F%20--%3E%7C%22%E5%90%A6%22%7C%20H%5B%22%E5%AE%9A%E7%A8%BF%EF%BC%9A%E4%BC%A0%E5%AF%BC%E9%93%BE%E4%B8%8E%E5%8A%A8%E4%BD%9C%E5%86%99%E5%85%A5%E6%83%85%E6%99%AF%E5%8D%A1%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a('<p><span class="marginnote">相关性翻转是压力情景的常规件：风险资产内部相关性在压力中趋近 \\(1\\)，股债相关性翻负——用常态协方差外推压力损失，方向与幅度都会错。2020 年 3 月连美国国债都出现变现折价，「无风险资产」的流动性假设也要写进情景。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么必须与分位数互补：二十个因子的高维联合尾部，在几年的日度样本里是空集——历史法对「同时坏」没有数据，参数法的椭圆假设把联合极端平滑掉了。情景是专家判断的结构化：把「什么机制能把账打到多深」写成因子路径、定价与资金联动的可计算对象；它接受审阅与挑战，因此本身是被登记、被验证的模型，与上一课的治理对接。传导链比终点重要：同样「跌三成」，纯价格冲击与「跌两成后被迫变现再补一成」的螺旋，对应完全不同的预防动作——前者减仓，后者先改融资结构。<a href="/quant/regime-break-risk">体制切换失效</a>课的结论在这里兑现：压力态的相关性与波动不是常态参数的外推，检测到切换就该触发情景更新。</p><p><span class="marginnote">给「传导链」代个数：假设持仓 10 亿，第一波跌 20% 亏 2 亿；保证金追缴要追加 1 亿现金，只能卖资产凑，卖压再吃 5% 折价，又亏约 0.5 亿——终点同样是「跌了 2.5 亿」，但「先改融资结构」能省掉那个 0.5 亿，光减仓省不掉。</span></p>',4)),(B(),s(n,null,{default:e(()=>[t(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20HIST%5B%22%E5%8E%86%E5%8F%B2%E6%83%85%E6%99%AF%EF%BC%9A%E8%B7%AF%E5%BE%84%E9%87%8D%E6%94%BE%22%5D%20--%3E%20LIB%5B%22%E6%83%85%E6%99%AF%E5%BA%93%EF%BC%9Aowner%20%E4%B8%8E%E6%9B%B4%E6%96%B0%E8%A7%A6%E5%8F%91%22%5D%0A%20%20HYP%5B%22%E5%81%87%E8%AE%BE%E6%83%85%E6%99%AF%EF%BC%9A%E6%9C%BA%E5%88%B6%E9%A9%B1%E5%8A%A8%22%5D%20--%3E%20LIB%0A%20%20SENS%5B%22%E6%95%8F%E6%84%9F%E6%80%A7%EF%BC%9A%E6%A2%AF%E5%BA%A6%E4%B8%8E%E7%9B%B8%E5%85%B3%E6%80%A7%E5%8A%A0%E5%8E%8B%22%5D%20--%3E%20LIB%0A%20%20LIB%20--%3E%20REVAL%5B%22%E8%81%94%E5%8A%A8%E9%87%8D%E4%BC%B0%EF%BC%9A%E5%B8%82%E5%9C%BA%E5%8A%A0%E8%B5%84%E9%87%91%22%5D%0A%20%20REVAL%20--%3E%20LIM%5B%22%E5%8E%8B%E5%8A%9B%E9%99%90%E9%A2%9D%22%5D%0A%20%20REVAL%20--%3E%20CAP%5B%22%E8%B5%84%E6%9C%AC%E8%A7%84%E5%88%92%22%5D%0A%20%20REVAL%20--%3E%20CFP%5B%22%E5%BA%94%E6%80%A5%E8%B5%84%E9%87%91%E8%AE%A1%E5%88%92%22%5D%0A%20%20MON%5B%22%E6%9C%AA%E9%81%82%E4%BA%8B%E4%BB%B6%E4%B8%8E%E5%8D%B1%E6%9C%BA%E7%9B%91%E6%B5%8B%22%5D%20--%3E%7C%22%E8%A7%A6%E5%8F%91%E6%9B%B4%E6%96%B0%22%7C%20LIB%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=a('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>反向压力测试不重写：正向库覆盖不到的机制，从损失阈值反推因子情景去补。监管压力测试（CCAR/DFAST 类）的宏观路径由监管给定，机构补的是执行质量与内部联动。压力通过不等于安全：情景是有限集合，未覆盖机制的暴露仍在，由反向测试与日常监测补。情景间的相关性不加总——「所有情景都过」不是风险总量的上界。</p><p><span class="marginnote">初学者容易以为「所有情景都通过 = 这家机构安全」：实际上情景库只是有限的考题集，考卷没出的题型照样会考。比如库里全是市场情景，而真正的爆点是清算系统瘫痪——全过也挡不住。这就是「压力通过不等于安全」的含义。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>压力测试的价值在结果进决策：限额、资本规划、应急计划三处对接缺一不可。</li><li>情景三层入库——历史、假设、敏感性，每个情景有 owner、传导链与更新触发。</li><li>严重度以历史段联合变动为锚，恶化假设由传导机制（如保证金螺旋）给出。</li><li>压力态的相关性与波动不是常态参数外推；体制切换检测触发情景更新。</li><li>出处：BCBS, <em>Principles for Sound Stress Testing Practices and Supervision</em>, 2009 年发布、2018 年修订；CEBS, <em>Guidelines on Stress Testing</em>, 2010；Brunnermeier and Pedersen, <em>Review of Economic Studies</em>, 2009；反向口径见本站反向压力测试课。</li></ul>',5))])}const h=i(d,[["render",C]]);export{c as __pageData,h as default};
